from typing import List

def find_divisible_number(n: int, arr: List[int]) -> int:
    min_val = min(arr)
    factors = set()

    def get_factors(x):
        i = 2
        while x > 1:
            if x % i == 0:
                factors.add(i)
                while x % i == 0:
                    x //= i
            i += 1

    get_factors(min_val)

    for factor in factors:
        valid = True
        for num in arr:
            if num % factor != 0:
                valid = False
                break
        if valid:
            return factor

    return -1

