    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:]))

    gcd = a[0]
    for num in a[1:]:
        while num != 0:
            if num < gcd:
                gcd, num = num, gcd
            gcd = gcd % num

    if all(num % gcd == 0 for num in a):
